import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer } from 'claude-code'

import {
  bandStage,
  bandText,
  effectiveTtlSeconds,
  fiveHourUsage,
  isHandoff,
  parseSubcommand,
  secondsLeft,
} from './model'

const COMMAND = 'cache-keeper'
const HANDOFF_SKILL = 'cache-keeper:session-handoff'

const now = atom({ plugin: 'cache-keeper', key: 'now' } as const, 0)
const cacheTouchedAt = atom({ plugin: 'cache-keeper', key: 'cacheTouchedAt' } as const, null)
const fiveHourPercent = atom({ plugin: 'cache-keeper', key: 'fiveHourPercent' } as const, null)
const fiveHourResetsAt = atom({ plugin: 'cache-keeper', key: 'fiveHourResetsAt' } as const, null)
const isHandingOff = atom({ plugin: 'cache-keeper', key: 'isHandingOff' } as const, false)
const isOn = atom({ plugin: 'cache-keeper', key: 'isOn' } as const, true)

type Engine = EngineInterface
type Config = { ttlSeconds: number; warnSeconds: number }

let ticker: Timer | undefined

async function refreshLimit($: Engine) {
  const usage = await $.session.usage()
  const fiveHour = fiveHourUsage(usage.rateLimits)
  await update($, fiveHourPercent, () => fiveHour?.percent ?? null)
  await update($, fiveHourResetsAt, () => fiveHour?.resetsAt ?? null)
}

async function claudeCodeTtl($: Engine, configured: number) {
  const fromEnv = await $.env.get('CLAUDE_CODE_PROMPT_CACHE_TTL')
  const settings: Record<string, unknown> = await $.settings.read()
  const fromSettings = settings.promptCacheTtl

  return effectiveTtlSeconds(configured, fromEnv ?? (typeof fromSettings === 'string' ? fromSettings : undefined))
}

async function startTicking($: Engine, cfg: Config) {
  ticker?.cancel()
  ticker = $.clock.every(1000, async () => {
    const at = await $.clock.now()
    await update($, now, () => at)
  })
}

async function turnOn($: Engine, cfg: Config) {
  await $.store.set('enabled', true)
  await update($, isOn, () => true)
  await startTicking($, cfg)
}

async function turnOff($: Engine) {
  await $.store.set('enabled', false)
  await update($, isOn, () => false)
  ticker?.cancel()
  ticker = undefined
}

async function runHandoff($: Engine) {
  await update($, isHandingOff, () => true)
  try {
    await $.command.run({ command: HANDOFF_SKILL })
  } catch {
    await $.prompt.submit({ text: `/${HANDOFF_SKILL}`, asUser: true })
  }
}

async function finishHandoff($: Engine) {
  await update($, isHandingOff, () => false)
  const replies = (await $.session.messages()).filter(m => m.role === 'assistant' && m.text !== '')
  const text = replies[replies.length - 1]?.text ?? ''
  if (!isHandoff(text)) {
    $.ui.toast('Handoff output was not in the expected format. The session was not cleared.')
    return
  }
  await $.store.set('handoff', text)
  $.clock.after(300, async () => {
    await $.command.run({ command: 'clear' })
    await $.prompt.fill({ text, mode: 'replace' })
    $.ui.toast('Handoff pasted into the new session. Press Enter to send it.')
  })
}

export const register: Register = (on, options) => {
  const cfg: Config = {
    ttlSeconds: Number(options.ttlSeconds ?? 3600),
    warnSeconds: Number(options.warnSeconds ?? 300),
  }

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: COMMAND,
      description: 'Show or hide the cache countdown bar',
      argumentHint: 'on | off | status',
    })
    cfg.ttlSeconds = await claudeCodeTtl($, cfg.ttlSeconds)
    const startedAt = await $.clock.now()
    await update($, now, () => startedAt)
    if ((await $.store.get('enabled')) === false) {
      await update($, isOn, () => false)
    } else {
      await turnOn($, cfg)
    }

    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    const word = parseSubcommand(e.args)
    if (word === 'invalid') return { text: 'Usage: /cache-keeper on | off | status' }
    if (word === 'on') {
      await turnOn($, cfg)
      return { text: 'cache-keeper is on.' }
    }
    if (word === 'off') {
      await turnOff($)
      return { text: 'cache-keeper is off.' }
    }

    return { text: (await read($, isOn)) ? 'cache-keeper is on.' : 'cache-keeper is off.' }
  })

  on('turn.step', async function* ($, e, next) {
    const stepStartedAt = await $.clock.now()
    await update($, cacheTouchedAt, () => stepStartedAt)

    return yield* next(e)
  })

  on('turn.complete', async ($, e, next) => {
    await refreshLimit($)
    if (await read($, isHandingOff)) await finishHandoff($)

    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    await refreshLimit($)

    return next(e)
  })

  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear') {
      await update($, cacheTouchedAt, () => null)
      }

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || !(await read($, isOn))) return next(e)

    const { Box, Text, Button } = $.ui.resolve(e)
    const left = secondsLeft(await read($, cacheTouchedAt), cfg.ttlSeconds, await read($, now))
    const percent = await read($, fiveHourPercent)
    const usage = percent === null ? null : { percent, resetsAt: await read($, fiveHourResetsAt) }
    const stage = bandStage(left, cfg.warnSeconds)
    const isCold = stage === 'cold'
    const color = stage === 'expired' ? 'red' : isCold ? 'yellow' : undefined

    return (
      <Box gap={1}>
        <Text color={color}>{bandText(left, usage)}</Text>
        {isCold && (
          <Button key="compact" label="Compact" onPress={() => $.command.run({ command: 'compact' })} />
        )}
        {isCold && <Button key="handoff" label="Handoff" onPress={() => runHandoff($)} />}
      </Box>
    )
  })
}

