export type Limit = { kind: string; percentUsed: number; resetsAt?: string }
export type Usage = { percent: number; resetsAt: string | null }

export function secondsLeft(
  lastRequestAt: number | null,
  ttlSeconds: number,
  now: number,
): number | null {
  if (lastRequestAt === null) return null
  const elapsed = Math.floor((now - lastRequestAt) / 1000)

  return Math.max(0, ttlSeconds - elapsed)
}

export function fiveHourUsage(limits: Limit[]): Usage | null {
  const fiveHour = limits.find(limit => limit.kind === 'five_hour')
  if (fiveHour === undefined) return null

  return { percent: Math.round(fiveHour.percentUsed), resetsAt: fiveHour.resetsAt ?? null }
}

export function formatResetTime(at: Date): string {
  const hours = at.getHours()
  const minutes = String(at.getMinutes()).padStart(2, '0')

  return `${hours % 12 || 12}:${minutes} ${hours < 12 ? 'am' : 'pm'}`
}

export type BandStage = 'waiting' | 'warm' | 'cold' | 'expired'

export function bandStage(left: number | null, warnSeconds: number): BandStage {
  if (left === null) return 'waiting'
  if (left === 0) return 'expired'

  return left <= warnSeconds ? 'cold' : 'warm'
}

export function bandText(left: number | null, usage: Usage | null): string {
  const cache =
    left === null
      ? 'Cache: waiting for first reply'
      : left === 0
        ? 'Cache expired'
        : left < 60
          ? 'Cache <1 min remaining'
          : `Cache ${Math.floor(left / 60)} min remaining`
  if (usage === null) return cache

  const resets = usage.resetsAt === null ? '' : ` resets at ${formatResetTime(new Date(usage.resetsAt))},`

  return `${cache}. Usage${resets} ${usage.percent}% used`
}

const CACHE_TTL_SECONDS: Record<string, number> = { '5m': 300, '1h': 3600 }

export function effectiveTtlSeconds(configured: number, claudeCodeTtl: string | undefined): number {
  return (claudeCodeTtl === undefined ? undefined : CACHE_TTL_SECONDS[claudeCodeTtl]) ?? configured
}

export function parseSubcommand(args: string): 'on' | 'off' | 'status' | 'invalid' {
  const word = args.trim().toLowerCase()
  if (word === '') return 'status'

  return word === 'on' || word === 'off' || word === 'status' ? word : 'invalid'
}

export function isHandoff(reply: string): boolean {
  return reply.trimStart().startsWith('## Handoff')
}

