      "default": 3600
    },
    "warnSeconds": {
      "type": "number",
      "title": "Warn when this many seconds remain",
      "description": "The bar turns yellow and shows the Compact and Handoff buttons when this many seconds remain.",
      "default": 300
    }
  }
}

